#nullable enable
class C
{
    bool M0(object obj) => false;

    void M1(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is var z
            ? x.ToString() // 1
            : y.ToString(); // unreachable
    }

    void M2(C? c)
    {
        int x, y;
        _ = c?.M0(x = 0) is var z
            ? x.ToString() // 2
            : y.ToString(); // unreachable
    }
}

